lib='''def nonframe_anchors(grid, frame=5):
    """The two cells outside any frame-colored region, as (color,(r,c)) pairs sorted left to right."""
    a=[]
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v!=0 and v!=frame:
                a.append((v,(r,c)))
    a.sort(key=lambda x:x[1][1])
    return a

def frame_interior(grid, frame=5):
    """(top,left,bottom,right) bounds of the region enclosed by the frame-colored border."""
    rows=[r for r,row in enumerate(grid) if frame in row]
    cols=[c for c in range(len(grid[0])) if any(row[c]==frame for row in grid)]
    return min(rows)+1,min(cols)+1,max(rows)-1,max(cols)-1

def fill_quadrants(grid, frame=5):
    """Fill the frame's interior with 2x2 blocks: main-diagonal quadrants get the left anchor color, anti-diagonal the right one."""
    grid=[row[:] for row in grid]
    (lc,_),(rc,_) = nonframe_anchors(grid, frame)
    t,l,b,r = frame_interior(grid, frame)
    hh=(b-t+1)//2; ww=(r-l+1)//2
    for i,(rs) in enumerate([(t,t+hh),(t+hh,b+1)]):
        for j,(cs) in enumerate([(l,l+ww),(l+ww,r+1)]):
            col = lc if i==j else rc
            for rr in range(*rs):
                for cc in range(*cs):
                    grid[rr][cc]=col
    return grid
'''
